    if (iw > ih * 1.15 && h > w * 1.15) { ctx.rotate(-Math.PI / 2); blit(ctx, img, -h / 2, -w / 2, h, w); }
    else if (ih > iw * 1.15 && w > h * 1.15) { ctx.rotate(Math.PI / 2); blit(ctx, img, -h / 2, -w / 2, h, w); }
