      const s = scale == null ? 1 : scale;
      const key = def.art;
      const dflt = ITEM_DEFAULT[key] || ITEM_DEFAULT.rock;
      const c1 = def.color || dflt[0], c2 = def.color2 || dflt[1];
      const R = Math.max(w, h) / 2;
