    let m = null;
    try { m = ctx.getTransform(); } catch (e) { m = null; }
    if (!m || !(Math.abs(m.a) + Math.abs(m.b) > 0)) return null;
    const q = Math.ceil(Math.hypot(m.a, m.b) * s * 4) / 4;
    if (!(q > 0) || q > 5) return null;
