    tone(ctx, c => rrect(c, -hw, -hh * 0.7, gl, h * 0.7, hh * 0.35), c2, -hw + gl / 2, 0, gl / 2, NOSPEC);
    ctx.beginPath();
    for (let i = 0; i < 3; i++) { const x = -hw + gl * (0.2 + i * 0.28); ctx.moveTo(x, -hh * 0.7); ctx.lineTo(x + gl * 0.16, hh * 0.7); }
