    ctx.beginPath(); ctx.moveTo(-r * 0.42, r * 0.3); ctx.quadraticCurveTo(-r * 0.36, -r * 0.35, 0, -r * 0.62); ctx.moveTo(r * 0.45, r * 0.42); ctx.quadraticCurveTo(r * 0.4, -r * 0.3, 0, -r * 0.62);
