    ctx.beginPath(); ctx.moveTo(0, -r * 0.62); ctx.quadraticCurveTo(r * 0.32, -r * 0.8, r * 0.16, -r * 0.94); S(ctx, INK, 2.2); ctx.stroke(); S(ctx, '#c9a36a', 1.1); ctx.stroke();
