          tone(ctx, c => poly(c, [-3, cy - 9, 3, cy - 9, 3, cy - 3, 9, cy - 3, 9, cy + 3, 3, cy + 3, 3, cy + 9, -3, cy + 9, -3, cy + 3, -9, cy + 3, -9, cy - 3, -3, cy - 3]), accC(PAL.lime), -8, cy, 9, { ol: 2, dark: -0.3 });
          txt(ctx, String(it.v == null ? '' : it.v), 10, cy + 0.5, 14, '#fff', true, 'center', INK);
