          ctx.beginPath(); ctx.moveTo(-11, -2); ctx.quadraticCurveTo(0, -4 - open, 11, -2); ctx.quadraticCurveTo(0, 2 + open, -11, -2); ctx.closePath();
          F(ctx, '#5a1030'); ctx.fill(); S(ctx, PAL.pink, 2); ctx.stroke();
          fangs(ctx, 0, -3 - open * 0.3, 3, 2.4);
