          if (k === 'grease') { F(ctx, '#ffe066'); ctx.beginPath(); circ(ctx, 10, cy + 7, 3); ctx.fill(); }
          if (k === 'steal') txt(ctx, '-', 11, cy - 7, 14, PAL.pink, true, 'center', INK);
