      g.fillStyle = INK; g.beginPath(); g.arc(px - pr * 0.32, py + pr * 0.05, pr * 0.13, 0, TAU); g.arc(px + pr * 0.32, py + pr * 0.05, pr * 0.13, 0, TAU); g.fill();
