    g.beginPath(); g.moveTo(x + 4 * s, cy + 8 * s); g.lineTo(x + 7 * s, cy); g.lineTo(x + w - 7 * s, cy); g.lineTo(x + w - 4 * s, cy + 8 * s); g.closePath();
