    g.fillStyle = 'rgba(255,255,255,0.8)'; g.beginPath(); g.arc(x + w * 0.27 - 0.8 * s, cy - 4.3 * s, 0.8 * s, 0, TAU); g.fill();
    g.fillStyle = P.g; g.beginPath(); g.arc(x + w * 0.68, cy + 3.5 * s, 3 * s, 0, TAU); g.fill(); g.strokeStyle = INK; g.stroke();
