    gr = g.createLinearGradient(0, -8 * s, 0, 9 * s); gr.addColorStop(0, '#22163f'); gr.addColorStop(1, '#0a0516');
    g.beginPath(); rrect(g, -20 * s, -8 * s, 40 * s, 17 * s, 8 * s); g.fillStyle = gr; g.fill(); g.lineWidth = 1.4 * s; g.strokeStyle = INK; g.stroke();
