    ttBlob(g, cx, fl, 300, '#ff4f9a', 0.22, 0.35);   // the horizon's haze
    ttBlob(g, cx, G.top + 70, 210, '#ff4f9a', 0.13);   // a soft halo behind the tower
    ttCity(g, w, G, 1, q);
