    const LAYOUT = { merge: 0.5, mergeR: 120, maxW: 516, life0: 0.55, lifeK: 0.055, lifeMax: 2.8, pad: 3, edge: 6, back: 0.9, sw: 540, sh: 960, far: 110, numMax: 80 };
