      F(ctx, 'rgba(255,255,255,0.28)'); ctx.beginPath(); ctx.ellipse(-r * 0.45, r * 0.32, r * 0.2, r * 0.1, -0.5, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI); ctx.closePath(); S(ctx, INK, lw); ctx.stroke();
      ctx.restore();
