      F(ctx, 'rgba(255,255,255,0.8)'); ctx.beginPath(); ctx.arc(-r * 0.6, -r * 0.34, r * 0.06, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, TAU); ctx.closePath(); S(ctx, INK, lw); ctx.stroke();
