      ctx.lineTo(gx, gy + s); ctx.lineTo(gx - s * 0.18, gy + s * 0.18); ctx.lineTo(gx - s, gy); ctx.lineTo(gx - s * 0.18, gy - s * 0.18); ctx.closePath();
      ctx.fill();
