        ctx.beginPath(); circ(ctx, 0, cy, 8.5); S(ctx, '#e8f4ff', 2); ctx.stroke(); ctx.setLineDash(NODASH); ctx.restore();
        txt(ctx, '?', 0, cy + 0.5, 11, '#e8f4ff', true, 'center', INK);
