    ctx.beginPath(); ctx.arc(0, 0, 11, 0, TAU); F(ctx, shade(PAL.gold, -0.62)); ctx.fill(); S(ctx, PAL.gold, 2); ctx.stroke();
    bestMiniClaw(ctx, 0, -4, 0.42, 0.4 + Math.sin(t * 4) * 0.3, t, 0);
    ctx.restore();
