      ctx.beginPath(); ctx.moveTo(-r * 0.6, -r - 30); ctx.lineTo(-r * 0.5, -r * 0.8); ctx.moveTo(r * 0.6, -r - 30); ctx.lineTo(r * 0.5, -r * 0.8); ctx.stroke();
