      tone(ctx, c => circ(c, 0, 0, r + 9), '#5a3414', 0, 0, r + 9, { dark: -0.35 });
      for (let i = 0; i < 16; i++) {
        const a = i / 16 * TAU, on = (i + Math.floor(t * (st.hi >= 0 ? 14 : 5))) % 3 === 0;
        ctx.beginPath(); circ(ctx, Math.cos(a) * (r + 4.5), Math.sin(a) * (r + 4.5), 2.4); F(ctx, on ? '#fff6c0' : '#8a6a2a'); ctx.fill();
      }
