          F(ctx, rgba('#f4ecff', 0.4 * (1 - u))); ctx.beginPath(); circ(ctx, ox + Math.sin(u * 6 + i) * r * 0.05, oy - r * 0.08 - u * r * 0.6, r * (0.06 + 0.1 * u)); ctx.fill();
