        ctx.beginPath(); ell(ctx, ox, oy, r * 0.3, r * 0.12, 0); F(ctx, 'rgba(26,15,46,0.72)'); ctx.fill();
        S(ctx, rgba(col, pul), Math.max(1, r * 0.05)); ctx.stroke();
