      tone(ctx, c => poly(c, [-s * 0.2, cy - r - s * 0.3, s * 0.2, cy - r - s * 0.3, 0, cy - r + s * 0.12]), PAL.blood, 0, cy - r - s * 0.1, s * 0.2, { ol: 1.5, spec: false });
