          ctx.beginPath(); for (let i = 0; i < 5; i++) ell(ctx, -r * 0.3 + i * r * 0.15, -r * 0.34 - (i % 2) * r * 0.05, r * 0.08, r * 0.035, 0); ctx.fill();
          const drop = (t * 0.9 + (seed & 7) * 0.13) % 1;
