          glow(ctx, px(1) * 0.5, py(1) * 0.5, r * 0.9, SEC_COL.amber, 0.35 * fl);
          tone(ctx, c => circ(c, px(1) * 0.5, py(1) * 0.5, r * 0.14), fl > 0.5 ? '#ffe2a6' : '#5a4a30', px(1) * 0.5, py(1) * 0.5, r * 0.14, NOSPEC);
