    '#2ee6d6': 'cyan', '#8dfff5': 'cyan', '#bfe8ff': 'cyan',
    '#3b6fd6': 'block', '#8fb6ff': 'block',
    '#ff2e88': 'pink', '#ff6bb0': 'pink',
    '#ffc94d': 'gold',
