  const WIN_RED = '#e8203a', WIN_GRN = '#2e9c4a', WIN_GOLD = '#ffc94d', WIN_SNOW = '#f4fbff';
  const WIN_BULBS = [WIN_RED, '#3ddc84', WIN_GOLD];
