          for (let i = 3; i >= 0; i--) q.quadraticCurveTo(sd * s * (i + 0.5) * 0.36, s * ((i % 2) ? 0.46 : 0.2), sd * s * i * 0.36, s * (i === 0 ? 0 : 0.24));
