      const bs = bw * 0.24 * bow;
      for (const sd of [-1, 1]) tone(ctx, q => ell(q, sd * bs * 0.75, -lidH / 2 - bs * 0.35, bs * 0.8, bs * 0.45, sd * -0.5), rib, sd * bs * 0.7, -lidH / 2 - bs * 0.35, bs * 0.6, { dark: -0.3, spec: false, ol: ol * 0.8 });
