          const a = -Math.PI / 2 + (winH(i, 1) - 0.5) * 2.2, v = 240 + winH(i, 2) * 260;
          const x = px + Math.cos(a) * v * tau, y = py - ph / 2 + Math.sin(a) * v * tau + 320 * tau * tau;
          if (y > fy + 110) continue;
          ctx.globalAlpha = U.clamp(1.2 - rev, 0, 1);
