    tone(ctx, c => { c.moveTo(-14, 9); c.lineTo(0, 16); c.lineTo(14, 9); c.lineTo(14, 13); c.lineTo(0, 20); c.lineTo(-14, 13); c.closePath(); }, '#ffffff', 0, 13, 10, { ol: 1.4, spec: false });
