      ctx.beginPath(); ctx.moveTo(sd * 1.5, -4); ctx.quadraticCurveTo(sd * 5, -8.5, sd * 10, -7); ctx.quadraticCurveTo(sd * 9, -1, sd * 5, -1); ctx.quadraticCurveTo(sd * 1.5, -1, sd * 1.5, -4); ctx.closePath();
