    S(ctx, rgba('#e8f4ff', 0.9), 1.2); ctx.beginPath();
    for (let i = 0; i < 3; i++) { const a = sp + i * TAU / 3; ctx.moveTo(0, 0); ctx.lineTo(Math.cos(a) * 6, Math.sin(a) * 2); }
    ctx.stroke(); ctx.restore();
