      const face = Math.floor(ang / Math.PI + 1e-6) % 2, cy = 470 - Math.sin(u * Math.PI) * 190, sy = Math.max(0.06, Math.abs(Math.cos(ang)));
      const fc = done ? win : face, r = 70;
