        if (live) { glow(ctx, cx, y, 90, col, 0.28 + Math.sin(t * 5) * 0.08); ctx.beginPath(); rrect(ctx, cx - w * 0.2, y - bh / 2 + 12, w * 0.4, bh - 24, 12); S(ctx, rgba(col, 0.7 + Math.sin(t * 6) * 0.3), 3); ctx.stroke(); }
