      ctx.bezierCurveTo(x + 104, y + h - 60, x + 112, y + h - 38, x + 140, y + h - 48); S(ctx, SCH_C.ink2, 2); ctx.stroke();
      txt(ctx, 'Prof. Pincher', x + 90, y + h - 30, 11, '#6a5a80', false, 'center');
