          glow(ctx, w * (0.7 + 0.08 * Math.cos(tt * 0.09)), fy * (0.3 + 0.06 * Math.sin(tt * 0.17)), 90, '#ff6bd6', 0.22);
          F(ctx, '#ffffff'); ctx.beginPath();
