            const x = 20 + i * (w - 40) / 6, a = Math.sin(tt * 1.3 + i * 0.9) * 0.28, L = 28 + legH(i, 8) * 26;
            ctx.save(); ctx.translate(x, 0); ctx.rotate(a);
            line(ctx, 0, 0, 0, L, '#1f7a2a', 2);
