          for (let i = 0; i < 10; i++) if (!flick || legH(i, Math.floor(tt * 0.7)) > 0.35) ctx.rect(20 + legH(i, 19) * (w - 80), fy * (0.45 + legH(i, 20) * 0.4), 4, 5);
