      for (let k = 0; k < 2; k++) { const ph = Math.floor(t * 12 + k * 7), j = pts[2 + (ph % 9)]; ctx.moveTo(j[0], j[1] - 8); ctx.lineTo(j[0] + 6, j[1] - 18); ctx.lineTo(j[0] - 2, j[1] - 22); ctx.lineTo(j[0] + 4, j[1] - 32); }
